insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source, published_at)
values ('RD-A2-046', 'A2', 'article', null, 11, 'Славонія – край пшеничних полів', 'Slavonija – zemlja žitnih polja',
        'Slavonija je ravničarski kraj na istoku Hrvatske, između rijeka Save, Drave i Dunava. Ljeti su posvuda žitna polja, kukuruz i suncokret. Slavonci su poznati kao vrlo gostoljubivi ljudi: gost uvijek mora nešto pojesti i popiti. Poznata jela su domaća kobasica, kulen i fiš paprikaš, koji se kuha u kotliću na vatri. Zimi se u mnogim obiteljima još održava svinjokolja, a jesen je vrijeme berbe grožđa. Slavonija je poznata i po tamburašima: bez tamburice nema slavlja. Najveći grad je Osijek, a vrijedi posjetiti i Vukovar i Đakovo, gdje se uzgajaju konji lipicanci.',
        'Славонія – рівнинний край на сході Хорватії, між річками Сава, Драва й Дунай. Улітку всюди пшеничні поля, кукурудза й соняшник. Славонці відомі як дуже гостинні люди: гість завжди мусить щось з''їсти й випити. Відомі страви – домашня ковбаса, кулен і фіш-паприкаш, який варять у казанку на вогні. Узимку в багатьох родинах ще влаштовують забій свиней, а осінь – час збору винограду. Славонія відома й своїми тамбурашами: без тамбурици немає свята. Найбільше місто – Осієк, а ще варто відвідати Вуковар і Джаково, де розводять коней-ліпіцанців.',
        '[{"form": "slavonija", "lemma": "Slavonija", "ua": "Славонія (край на сході Хорватії)", "lesson": true, "pos": "назва місця"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно"}, {"form": "ravničarski", "lemma": "ravničarski", "ua": "рівнинний", "lesson": true, "pos": "прикметник"}, {"form": "kraj", "lemma": "kraj", "ua": "кінець; край, місцевість", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "istoku", "lemma": "istok", "ua": "схід", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "hrvatske", "lemma": "Hrvatska", "ua": "Хорватія", "lesson": true, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "između", "lemma": "između", "ua": "між", "lesson": true, "pos": "прийменник + родовий відмінок"}, {"form": "rijeka", "lemma": "rijeka", "ua": "річка", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), множина"}, {"form": "save", "lemma": "Sava", "ua": "Сава (річка)", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "drave", "lemma": "Drava", "ua": "Драва (річка)", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "dunava", "lemma": "Dunav", "ua": "Дунай", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "ljeti", "lemma": "ljeti", "ua": "улітку", "lesson": true, "pos": "прислівник"}, {"form": "su", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); ко