ue, "pos": "питальний прислівник «де»"}, {"form": "uzgajaju", "lemma": "uzgajati", "ua": "вирощувати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "konji", "lemma": "konj", "ua": "кінь", "lesson": false, "pos": "іменник, чоловічий рід", "gram": "називний відмінок (хто? що?), множина"}, {"form": "lipicanci", "lemma": "lipicanac", "ua": "ліпіцанер (порода коней)", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "називний відмінок (хто? що?), множина"}]'::jsonb,
