values ('RD-A2-050', 'A2', 'notice', 'small_talk', 12, 'День Незалежності України в Загребі', 'Dan neovisnosti Ukrajine u Zagrebu',
        'Ukrajinska zajednica u Zagrebu poziva sve Ukrajince i njihove prijatelje na obilježavanje Dana neovisnosti Ukrajine 24. kolovoza. Okupljanje je u 11 sati ispred kulturnog društva, a zatim idemo zajedno u grkokatoličku crkvu. Poslije podne djeca iz subotnje škole imaju nastup s pjesmama i plesovima. Za goste će biti ukrajinska i hrvatska hrana. Udruga traži i nove volontere: ako znate hrvatski, možete pomoći kao prevoditelj volonter novopridošlim obiteljima. Dođite, upoznajte nove ljude i osjećajte se kao kod kuće! Ulaz je slobodan.',
        'Українська громада в Загребі запрошує всіх українців та їхніх друзів відзначити День Незалежності України 24 серпня. Збір об 11 годині перед культурним товариством, а потім ідемо разом до греко-католицької церкви. По обіді діти з суботньої школи виступлять із піснями й танцями. Для гостей буде українська й хорватська їжа. Об''єднання також шукає нових волонтерів: якщо ви знаєте хорватську, можете допомагати як перекладач-волонтер новоприбулим родинам. Приходьте, знайомтеся з новими людьми й почувайтеся як удома! Вхід вільний.',
        '[{"form": "ukrajinska", "lemma": "ukrajinski", "ua": "українська (мова); український", "lesson": true, "pos": "прикметник «український»; як іменник — українська мова", "gram": "називний відмінок (хто? що?), однина, ж. р."}, {"form": "zajednica", "lemma": "ukrajinska zajednica", "ua": "українська громада", "lesson": true, "pos": "сталий вираз", "gram": "частина сталого виразу «ukrajinska zajednica»"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб (столиця Хорватії)", "lesson": false, "pos": "назва місця", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "poziva", "lemma": "pozivati", "ua": "запрошувати", "lesson": false, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: він / вона / воно"}, {"form": "sve", "lemma": "sav", "ua": "весь; усі", "lesson": false, "pos": "займенник «весь, усі»", "gram": "знахідний відмінок (кого? що?), множина, ч. р."}, {"form": "ukrajince", "lemma": "Ukrajinac", "ua": "українець", "lesson": true, "pos": "ім’я (чоловіче)", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "njihove", "lemma": "njihov", "ua": "їхній", "lesson": true, "pos": "займенник", "gram": "знахідний відмінок (кого? що?), множина, ч. р."}, {"form": "prijatelje", "lemma": "prijatelj", "ua": "друг", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "obilježavanje", "lemma": "obilježavanje", "ua": "відзначення (свята)", "lesson": false, "pos": "іменник, середній рід"}, {"form": "dana", "lemma": "Dan neovisnosti Ukrajine", "ua": "День Незалежності України", "lesson": true, "pos"