values ('RD-A2-053', 'A2', 'chat', 'small_talk', 13, 'Переносимо зустріч', 'Pomaknimo dogovor',
        'Daša: Bok, Ivana! Ispričavam se, ali iskrsnulo mi je nešto na poslu. Ne stižem danas na kavu u pet.
Ivana: Nema problema! Možemo li pomaknuti dogovor na sutra?
Daša: Sutra mi je raspored pun. Odgovara li ti subota ujutro?
Ivana: Subota je super. Recimo u deset na Trgu?
Daša: Dogovoreno! Ako se išta promijeni, javit ću ti.
Ivana: Važi. I nemoj otkazati u zadnji čas kao prošli put!
Daša: Neću, obećavam! Veselim se, vidimo se onda u subotu.
Ivana: Vidimo se!',
        'Даша: Привіт, Івано! Перепрошую, але в мене дещо трапилося на роботі. Я не встигаю сьогодні на каву о п''ятій.
Івана: Без проблем! Можемо перенести зустріч на завтра?
Даша: Завтра в мене щільний розклад. Тобі підходить субота вранці?
Івана: Субота – чудово. Скажімо, о десятій на Площі?
Даша: Домовилися! Якщо щось зміниться, я тобі напишу.
Івана: Гаразд. І не скасовуй в останню мить, як минулого разу!
Даша: Не скасую, обіцяю! Чекаю з радістю, тоді побачимося в суботу.
Івана: До зустрічі!',
        '[{"form": "daša", "lemma": "Daša", "ua": "Даша (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "bok", "lemma": "bok", "ua": "привіт / бувай", "lesson": true, "pos": "вигук"}, {"form": "ivana", "lemma": "Ivana", "ua": "Івана (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "ispričavam", "lemma": "ispričavati se", "ua": "перепрошувати", "lesson": false, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: я"}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false, "pos": "зворотний займенник «себе / -ся» (коротка форма; стоїть на другому місці в реченні)"}, {"form": "ali", "lemma": "ali", "ua": "але", "lesson": true, "pos": "сполучник"}, {"form": "iskrsnulo", "lemma": "iskrsnulo mi je nešto", "ua": "у мене дещо непередбачене", "lesson": true, "pos": "сталий вираз", "gram": "частина сталого виразу «iskrsnulo mi je nešto»"}, {"form": "mi", "lemma": "mi", "ua": "ми; мені", "lesson": true, "pos": "займенник «ми»; також «мені» — коротка форма давального від ja"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно"}, {"form": "nešto", "lemma": "nešto", "ua": "щось", "lesson": true, "pos": "займенник «щось»"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "poslu", "lemma": "posao", "ua": "робота / справа", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "ne", "lemma": "ne", "ua": "не (заперечення); ні", "lesson": true, "pos": "частка"}, {"form": "stižem", "lemma": "ne stižem", "ua": "я не встигаю", "lesson": true, "pos": "сталий вираз", "gram": "частина сталого виразу «ne stižem»"}, {"form": "danas", "lemma": "danas", "ua": "сьогодні", "lesson": true, "pos": "прислівник"}, {"fo