values ('RD-A2-056', 'A2', 'email', 'small_talk', 14, 'Лист подрузі: я даю собі раду', 'Pismo prijateljici',
        'Draga Oksana,
hvala ti na pismu, jako mi nedostaješ! Imam puno novosti. Ukratko: napokon sam položila ispit iz hrvatskog! Sada se puno bolje snalazim u svakodnevnim situacijama. Prošli tjedan sam bila kod liječnika i sama sam opisala simptome, bez prevoditelja. Na poslu sam se samostalno dogovorila sa šefom oko godišnjeg odmora. Prije dvije godine to nisam mogla ni zamisliti. Naravno, još uvijek griješim, ali učim iz pogrešaka. Imam više samopouzdanja i osjećam da je ovo novo poglavlje u mom životu. Kad dolaziš u posjet? Jedva čekam da te vidim!
Piši mi i pozdravi svoje!
Tvoja Darja',
        'Дорога Оксано!
Дякую тобі за листа, я дуже за тобою сумую! У мене багато новин. Коротко: нарешті я склала іспит з хорватської! Тепер я набагато краще даю собі раду в щоденних ситуаціях. Минулого тижня я була в лікаря й сама описала симптоми, без перекладача. На роботі я самостійно домовилася з шефом про відпустку. Два роки тому я не могла навіть уявити цього. Звісно, я ще помиляюся, але вчуся на помилках. Я стала впевненішою в собі й відчуваю, що це новий розділ у моєму житті. Коли ти приїдеш у гості? Не можу дочекатися, щоб тебе побачити!
Пиши мені й передавай вітання своїм!
Твоя Дар''я',
        '[{"form": "draga", "lemma": "drag", "ua": "дорогий; милий, приємний", "lesson": true, "pos": "прикметник", "gram": "кличний відмінок (звертання), однина, ж. р."}, {"form": "oksana", "lemma": "Oksana", "ua": "Оксана (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true, "pos": "частка"}, {"form": "ti", "lemma": "ti", "ua": "ти", "lesson": true, "pos": "особовий займенник «ти»"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "pismu", "lemma": "pismo", "ua": "лист", "lesson": true, "pos": "іменник, середній рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "jako", "lemma": "jako", "ua": "дуже", "lesson": false, "pos": "прислівник «дуже»"}, {"form": "mi", "lemma": "mi", "ua": "ми; мені", "lesson": true, "pos": "займенник «ми»; також «мені» — коротка форма давального від ja"}, {"form": "nedostaješ", "lemma": "nedostaješ mi", "ua": "я сумую за тобою", "lesson": true, "pos": "сталий вираз", "gram": "частина сталого виразу «nedostaješ mi»"}, {"form": "imam", "lemma": "imati", "ua": "мати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: я"}, {"form": "puno", "lemma": "puno", "ua": "багато", "lesson": true, "pos": "прислівник «багато» + родовий («puno turista»)"}, {"form": "novosti", "lemma": "novosti", "ua": "новини (особисті)", "lesson": true, "pos": "іменник, ж. р., лише множина"}, {"form": "ukratko", "lemma": "ukratko", "ua": "коротко", "lesson": true, "pos": "прислівник"}, {"form": "napokon", "lemma": "napokon", "ua": "врешті-решт", "lesson": true, "pos": "прислівник"}, {"form": "sam", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: я"}, {"form": "položila", "lemma": "položiti", "ua": "скласти (іспит)", "lesson": t