-- Журнал перевірки (один запис на текст)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'reading_text', r.id, null, r.status, 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тексти для читання A2 за програмою A2 v2 (4 на модуль), reading_a2_v2 2026-11-13. Знайомі слова — уроки A0, A1 і A2 до модуля тексту. Потрібна перевірка носієм.'
from public.reading_texts r
where r.code in ('RD-A2-045', 'RD-A2-046', 'RD-A2-047', 'RD-A2-048', 'RD-A2-049', 'RD-A2-050', 'RD-A2-051', 'RD-A2-052', 'RD-A2-053', 'RD-A2-054', 'RD-A2-055', 'RD-A2-056')
  and not exists (select 1 from public.content_reviews c where c.entity_id = r.id and c.notes = 'Бета: тексти для читання A2 за програмою A2 v2 (4 на модуль), reading_a2_v2 2026-11-13. Знайомі слова — уроки A0, A1 і A2 до модуля тексту. Потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_total int; v_bad int;
begin
  select count(*) into v_total from public.reading_texts
   where code in ('RD-A2-045', 'RD-A2-046', 'RD-A2-047', 'RD-A2-048', 'RD-A2-049', 'RD-A2-050', 'RD-A2-051', 'RD-A2-052', 'RD-A2-053', 'RD-A2-054', 'RD-A2-055', 'RD-A2-056') and cefr = 'A2' and status = 'PUBLISHED' and source = 'claude_reading_a2_v2' and module_order between 1 and 14;
  select count(*) into v_bad from public.reading_texts r where r.code in ('RD-A2-045', 'RD-A2-046', 'RD-A2-047', 'RD-A2-048', 'RD-A2-049', 'RD-A2-050', 'RD-A2-051', 'RD-A2-052', 'RD-A2-053', 'RD-A2-054', 'RD-A2-055', 'RD-A2-056')
     and (jsonb_array_length(r.questions) <> 3 or r.known_ratio < 0.9
          or exists (select 1 from jsonb_array_elements(r.glossary) e
                     where e->>'pos' is null or coalesce(e->>'ua', '') = ''
                        or (e->>'gram' is null and e->>'form' <> lower(e->>'lemma'))));
  if v_total <> 12 then raise exception 'Нових текстів A2 %, очікувалось 12 (код уже зайнятий іншим текстом?)', v_total; end if;
  if v_bad > 0 then raise exception '% текстів без питань, словничка чи граматичних підказок', v_bad; end if;
  raise notice 'Готово: нових текстів A2 у частині 3 — % (RD-A2-045 … RD-A2-056)', v_total;
end $$;

-- Підсумок рівня: 4 тексти в кожному з 14 модулів A2
do $$
declare v_bad int; v_all int;
begin
  select count(*) into v_all from public.reading_texts where cefr = 'A2' and status = 'PUBLISHED';
  select count(*) into v_bad from (
    select m.n, count(r.id) c from generate_series(1, 14) m(n)
    left join public.reading_texts r on r.cefr = 'A2' and r.status = 'PUBLISHED' and r.module_order = m.n
    group by m.n) x where x.c < 4;
  if v_bad > 0 then raise exception 'У % модулях A2 менше 4 текстів (спершу частина 1?)', v_bad; end if;
  raise notice 'Готово: текстів A2 разом — % (по 4 у кожному з 14 модулів)', v_all;
end $$;

commit;
